 "content": "def transform(grid):
    out=[row[:] for row in grid]
    rows=[r for r,row in enumerate(grid) if 3 in row]
    cols=[c for c in range(len(grid[0])) if any(row[c]==3 for row in grid)]
    t,b,l,rr=min(rows),max(rows),min(cols),max(cols)
    mark=next(((r,c) for r in range(t+1,b) for c in range(l+1,rr) if grid[r][c]==3),None)
    if mark is None: return out
    mr,mc=mark
    # The marker is the seed of the filled ray pattern. The lines alternate
    # in orientation as they advance from the seed, leaving intervening 4s.
    for r in range(t+1,b):
        for c in range(l+1,rr): out[r][c]=4
    out[mr][mc]=3
    # Vertical ray through the seed and horizontal ray through its row.
    for r in range(mr+1,b):
        if (r-mr)%2==1:
            for c in range(l+1,rr): out[r][c]=2
    for r in range(t+1,b):
        if (r-mr)%2==0 and r!=mr:
            for c in range(l+1,rr):
                if (c-mc)%2==0: out[r][c]=2
    for c in range(l+1,rr):
        if (c-mc)%2==0:
            for r in range(t+1,mr): out[r][c]=2
    return out
